  (710293, (SELECT id FROM locales WHERE code = 'et'), 'Vita 2013: 8 patsienti, sama annus kapslina; kohv 1 h või ≤5 min hiljem.'),
  (710294, (SELECT id FROM locales WHERE code = 'et'), 'Kapslile ülemineku järel ei erinenud TSH kahe kohviajastuse vahel oluliselt (p=0,90); tabletiga enne vahetust erines (p<0,0001). Väike valitud rühm; ei tõenda kõigi ravimvormide koostoime puudumist.'),
