  (710304, (SELECT id FROM locales WHERE code = 'et'), 'Loomuuring osutab võimalikule plasmakontsentratsiooni suurenemisele. Autorid soovitavad greibimahlaga ettevaatust ja kliinilist jälgimist, kuid inimeste verejooksuriski ei uuritud. Kooskasutamist arutada tervishoiutöötajaga.'),
