  (710541, (SELECT id FROM locales WHERE code = 'et'), 'Rivaroksabaan + Naistepuna'),
  (710542, (SELECT id FROM locales WHERE code = 'et'), 'Rivaroksabaan; otsene uuringutõendus. Mitte kõigi antikoagulantide ühine reegel.'),
  (710543, (SELECT id FROM locales WHERE code = 'et'), 'Kooskasutamine, sh hüperforiini sisaldav ekstrakt; väikesed tervete vabatahtlike uuringud.'),
  (710544, (SELECT id FROM locales WHERE code = 'et'), 'Naistepuna vähendas rivaroksabaani ekspositsiooni ja ühes uuringus Xa-vastast toimet. 2018. aasta uuring soovitab vältida; 2021. aasta uuring kaaluda vältimist või laboratoorset jälgimist, kuid ei põhjenda automaatset vastunäidustust ega süstemaatilist annusemuutust.

