  (710764, (SELECT id FROM locales WHERE code = 'et'), 'PPI-d võivad vähendada suukaudse raua imendumist. Rauaravi vastuse hindamisel arvestada PPI kasutamist; allikast ei tulene PPI automaatset lõpetamist ega kinnitatud ajastusvahet, mis mõju kõrvaldaks.'),
  (710771, (SELECT id FROM locales WHERE code = 'et'), 'Digoksiin; glütsürritsiini sisaldav lagrits + lagrits'),
  (710772, (SELECT id FROM locales WHERE code = 'et'), 'Eraldi paar / rühma liikmed. 11β-HSD2 pärssimine → kortisooli mineralokortikoidne toime → Na/vee peetus ja K kadu; hüpokaleemia suurendab tundlikkust digoksiinile.'),
  (710773, (SELECT id FROM locales WHERE code = 'et'), 'Otsene tõendus: Harada haigusjuht. Mehhanism: Stewart inimkatse (n=7). Segapreparaat ja kaasravimid piiravad põhjuslikku järeldust.'),
  (710774, (SELECT id FROM locales WHERE code = 'et'), 'Digoksiinitoksilisuse ja rütmihäirete oht.
Olulisus: Potentsiaalselt raske; lisarisk kaaliumi vähendavate diureetikumidega.
Juhis: Vältida glütsürritsiini sisaldavaid tooteid. Mõnetunnine vahe ei kõrvalda elektrolüütide kaudu tekkivat riski.
Arvuline mõju: Usaldusväärne üldine riskikordaja puudub; ei ole nullrisk.'),
