  (40027, 30008, 1, 'Samaaegsel tarvitamisel on kirjeldatud kliiniliselt olulist levotüroksiini imendumise vähenemist.', 'Koosmanustamisel.', 'Täpset lehekülge/jaotist ei ole alusmaterjalis esitatud.', 'MD soovituse mustand: Arvestada koostoimega ja küsida nõu manustamisvahe kohta.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40028, 30009, 1, 'Tervetel eutüreoidsetel katsealustel oli levotüroksiinilahuse ja tableti biosaadavus tühja kõhuga võrreldav. See tulemus ei tõenda kohviga koosmanustamise mõju puudumist.', 'Randomiseeritud ühekordse annuse kaheperioodiline ristuvuuring tervetel katsealustel tühja kõhuga; võrdlus oli lahus versus tablett, mitte kohviga versus kohvita.', 'Abstrakt.', 'Võimalik väiksem tundlikkus kohvist tingitud imendumishäirele on taustpõhjendus. Konkreetse kohviga koosmanustamise järeldus vajab eraldi tõendust.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40010, 30010, 1, 'AUC −36% patsientidel / −27% vabatahtlikel; T4 tipptaseme tõus −30% / −19%; tipuni jõudmine hilines 38 / 43 min.', '6 patsienti + 9 vabatahtlikku; 200 µg tablett; kohv vs vesi.', 'Abstrakt; Thyroid 18:293–301', 'Vesi + kohv 60 min hiljem andis veega sarnase tulemuse; kohvi siduv toime toetatud in vitro.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40028, 30011, 1, 'TSH hommikusöögi juures 2,5 ± 1,1; 30 min enne sööki 3 kuu järel 2,5 ± 1,1 ja 6 kuu järel 2,4 ± 1,1 mIU/l; olulist erinevust ei leitud.', '54 stabiilset patsienti; sama vedela LT4 annus; enne-pärast uuring.', 'Abstrakt; EJE 170:95–99', 'Lahuse tulemust ei üldistata tablettidele.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40029, 30012, 1, 'Pehmekapslile ülemineku järel TSH kohv 1 h vs ≤5 min hiljem: erinevus puudus (p=0,90); tablettidega enne vahetust erines (p<0,0001).', '8 valitud patsienti; 6 kuud; PK lisakatse ainult 2 patsiendil.', 'Abstrakt; Endocrine 43:154–160', 'Ravimvormide eristamine oluline. Ei anna universaalset kohviga manustamise luba.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40030, 30013, 1, 'Rottide farmakokineetilises uuringus käsitleti greibimahla koostoimet rivaroksabaani ja tikagrelooriga. Autorid järeldavad, et plasmakontsentratsioon võib suureneda; patsiendi verejooksuriski uuring ei mõõtnud.', 'Loomuuring rottidel; inimese osalusega katseid ei tehtud. Selles juhtumis käsitletakse rivaroksabaani.', 'Abstrakt; Ethical conduct of research.', 'Autorite soovitus ettevaatuseks ja kliiniliseks jälgimiseks on loomkatse põhjal esitatud kliiniline tõlgendus. Inimese riski suurus ja annustamisreegel ei ole tõendatud.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40031, 30014, 1, 'Greibimahl suurendas rottidel apiksabaani plasmakontsentratsiooni ja süsteemset ekspositsiooni.', 'Rottide in vivo farmakokineetiline uuring greibimahlaga ja ilma; inimese kliinilist tulemust ei hinnatud.', 'Artikli pealkiri ja abstrakt.', 'Loomkatseleid. Kliinilist verejooksuriski ega patsiendipõhist annustamissoovitust ei saa sellest uuringust määrata.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40032, 30015, 1, 'Naistepuna kooskasutamisel on inimestel kirjeldatud selle ravimi kontsentratsiooni vähenemist veres.', 'Kooskasutamine; toime sõltub ka naistepuna annusest, manustamisviisist ja kestusest.

Mõju võib varieeruda naistepuna annuse, manustamisviisi ja kasutamise kestuse järgi.', 'Täpset lehekülge/jaotist ei ole alusmaterjalis esitatud.', 'MD soovituse mustand: Enne kooskasutamist kontrollida võimalikke ravitoime vähenemisega seotud riske.

