  (40034, 30018, 1, '10 päeva järel AUC −25% (17,2 → 12,9 µg·h/l; p=0,0035); Cmax −26%, minimaalne kontsentratsioon −33%.', '25 tervet vabatahtlikku: 13 LI160 900 mg/päev, 12 platseebo; digoksiin 0,25 mg/päev.', 'Abstrakt; Clin Pharmacol Ther 66:338–345', 'Võimalik P-gp induktsioon; ajast sõltuv mõju, mitte kohene ühe annuse koostoime.', NULL, 'healthy_volunteers', 25, 'auc_percent_change', -25, NULL, NULL, 0.0035, 'digoksiini AUC 10 päeva järel; Cmax −26%', 'draft'),
  (40049, 30019, 1, 'Pikaajaline prootonpumba inhibiitorite tarvitamine võib seostuda selle mikrotoitaine puudusega, sest maohape on oluline imendumisel ja biosaadavusel.', 'Pikaajaline kasutamine; konkreetseid annuseid ei ole esitatud.

Ülevaate tsitaat ei tõenda kõigi üksikute ravimite kohta sama toime suurust.', 'Kokkuvõte; täpne lehekülg kontrollimata.', 'Ülevaade käsitleb pikaajalist PPI kasutamist ja võimalikke puudusi. Üldist rühmaväidet ei kasutata üksikravimi toime suuruse, mikrotoitaine annuse ega universaalse kestuselävendi määramiseks.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
