  (40069, 30028, 1, 'C-vitamiin soodustab suu kaudu võetava raua imendumist.', 'Allikakatke soovitab hommikust tühja kõhuga manustamist koos ligikaudu 100 mg C-vitamiiniga.', 'Kokkuvõte; jaotised raua imendumise mehhanismidest ja kliinilistest soovitustest; Box 2.', 'Praktiline ülevaade; soovitused ja näidisannused ei ole iga teguripaari eraldi kliiniline uuring. Imendumise muutus ei määra kõigi patsientide ravitulemust; ravimi ärajätmist või universaalset ohutut annustamisvahet ei tuletata.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40058, 30028, 1, 'Kohviga võtmine vähendab suukaudse raua imendumist märgatavalt.', 'Raualisandi samaaegne tarvitamine kohviga.', 'Kokkuvõte; jaotised raua imendumise mehhanismidest ja kliinilistest soovitustest; Box 2.', 'Praktiline ülevaade; soovitused ja näidisannused ei ole iga teguripaari eraldi kliiniline uuring. Imendumise muutus ei määra kõigi patsientide ravitulemust; ravimi ärajätmist või universaalset ohutut annustamisvahet ei tuletata.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
