  (40075, 30028, 1, 'See tegur vähendab suukaudse raua imendumist.', 'Samaaegne tarvitamine.', 'Kokkuvõte; jaotised raua imendumise mehhanismidest ja kliinilistest soovitustest; Box 2.', 'Praktiline ülevaade; soovitused ja näidisannused ei ole iga teguripaari eraldi kliiniline uuring. Imendumise muutus ei määra kõigi patsientide ravitulemust; ravimi ärajätmist või universaalset ohutut annustamisvahet ei tuletata.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40076, 30028, 1, 'See tegur vähendab suukaudse raua imendumist.', 'Samaaegne tarvitamine.', 'Kokkuvõte; jaotised raua imendumise mehhanismidest ja kliinilistest soovitustest; Box 2.', 'Praktiline ülevaade; soovitused ja näidisannused ei ole iga teguripaari eraldi kliiniline uuring. Imendumise muutus ei määra kõigi patsientide ravitulemust; ravimi ärajätmist või universaalset ohutut annustamisvahet ei tuletata.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40064, 30029, 1, 'Toiduraua imendumine kohviga −39%. 1 h pärast toidukorda joodud kohv pärssis samuti; 1 h enne mitte.', 'Toidukorra imendumisuuring; mitte raviannuses rauatableti katse.', 'Abstrakt', 'Ei määra aneemiaravi pikaajalist tulemust.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40058, 30030, 1, 'Praktiline juhis: võtta rauda veega, toidust/kohvist eraldi vähemalt 1 h enne või 2 h pärast.', 'Ravimiinfo/juhis; seedetraktitalumatuse korral võib toiduga manustamine sobida.', 'Manustamine', 'See ajavahemik pärineb juhisest, mitte 2023. aasta katse eraldi ajastusvõrdlusest.', 'label', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40064, 30029, 2, 'Mitteheemse raua imendumine; suhteline muutus -39.0%. —', 'Morck 1983; hamburgerieine + kohv', '1 + avaldatud suhteline muutus', 'Uuritud toidukorra tulemus; kohv 1 h pärast sööki samuti pärssis.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40058, 30026, 2, 'Raua fraktsionaalne imendumine; suhteline muutus -54.0%. p=0,004', 'n=34 rauavaegusega naist; 100 mg rauda; kohv vs hommikul veega', '1 + avaldatud suhteline muutus', 'Ei tähenda vere hemoglobiini 54% vähenemist.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40058, 30026, 3, 'Raua fraktsionaalne imendumine; suhteline muutus -66.0%. p<0,001', 'Sama katse; hommikusöögis ka ~90 mg askorbiinhapet', '1 + avaldatud suhteline muutus', 'Kombineeritud toidumõju, mitte üksnes kohvi mõju.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40077, 30031, 1, 'Digoksiinitoksilisuse ja rütmihäirete oht. Usaldusväärne üldine riskikordaja puudub; ei ole nullrisk.', 'Otsene tõendus: Harada haigusjuht. Mehhanism: Stewart inimkatse (n=7). Segapreparaat ja kaasravimid piiravad põhjuslikku järeldust.', 'Uuringu kokkuvõte / ravimiinfo', 'Vältida glütsürritsiini sisaldavaid tooteid. Mõnetunnine vahe ei kõrvalda elektrolüütide kaudu tekkivat riski.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40077, 30032, 1, '11β-HSD2 pärssimine → kortisooli mineralokortikoidne toime → Na/vee peetus ja K kadu; hüpokaleemia suurendab tundlikkust digoksiinile.', 'Otsene tõendus: Harada haigusjuht. Mehhanism: Stewart inimkatse (n=7). Segapreparaat ja kaasravimid piiravad põhjuslikku järeldust.', 'Lisauuring / ravimiinfo; vt lingitud allikat', 'Vältida glütsürritsiini sisaldavaid tooteid. Mõnetunnine vahe ei kõrvalda elektrolüütide kaudu tekkivat riski.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40078, 30033, 1, 'Amiodarooni ekspositsioon suureneb, aktiivse metaboliidi teke väheneb. AUC +50%; Cmax +84%; N-DEA teke uuringus täielikult pärsitud.', 'n=11; 17 mg/kg amiodarooni ja 3 × 300 ml greibimahla. Suur ühekordne annus; raskeid rütmihäireid ei tõendatud.', 'Uuringu kokkuvõte / ravimiinfo', 'Greibimahla vältida.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40078, 30034, 1, 'CYP3A4 pärssimine vähendab metabolismi N-desetüülamiodarooniks.', 'n=11; 17 mg/kg amiodarooni ja 3 × 300 ml greibimahla. Suur ühekordne annus; raskeid rütmihäireid ei tõendatud.', 'Lisauuring / ravimiinfo; vt lingitud allikat', 'Greibimahla vältida.', 'label', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40078, 30033, 2, 'AUC; kontroll 23.9 → koos / teine skeem 35.9 µg·h/ml; suhteline muutus 50.0%. p<0,005', 'n=11; 17 mg/kg; greibimahl 3 × 300 ml', '1 + avaldatud suhteline muutus', 'Avaldatud keskmised; mitte kõrvaltoimerisk.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40078, 30033, 3, 'Cmax; kontroll 1.87 → koos / teine skeem 3.45 µg/ml; suhteline muutus 84.0%. p<0,02', 'Sama katse', '1 + avaldatud suhteline muutus', 'Üksikannus; N-DEA teke täielikult pärsitud.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40079, 30035, 1, 'Suureneda võivad biosaadavus ja vererõhku langetav toime; toimeained erinevad. Felodipiini koostoime esines ka greibimahla 24 h varasemal võtmisel.', 'Farmakokineetiline muutus ei võrdu kõrvaltoimete sama suure muutusega.', 'Uuringu kokkuvõte / ravimiinfo', 'Järgida toimeaine juhist. Greibi ja ravimi eri kellaaeg ei taga koostoime vältimist.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40079, 30036, 1, 'Eeskätt sooleseina CYP3A4 pärssimine → presüsteemse metabolismi vähenemine.', 'Farmakokineetiline muutus ei võrdu kõrvaltoimete sama suure muutusega.', 'Lisauuring / ravimiinfo; vt lingitud allikat', 'Järgida toimeaine juhist. Greibi ja ravimi eri kellaaeg ei taga koostoime vältimist.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40080, 30036, 1, 'Tugevam vererõhulangus, kiirem pulss ja vasodilatatsiooni kõrvaltoimed. Biosaadavus 2,84-kordne (vahemik 1,64–4,69); teises uuringus AUC +73%, Cmax +138% esimesel päeval.', 'Bailey: n=6; felodipiin 5 mg. Teine uuring: n=12; ER 10 mg, 14 päeva. Tulemused sõltuvad tingimustest.', 'Uuringu kokkuvõte / ravimiinfo', 'Greipi vältida.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40080, 30037, 1, 'Sooleseina CYP3A metabolismi pärssimine.', 'Bailey: n=6; felodipiin 5 mg. Teine uuring: n=12; ER 10 mg, 14 päeva. Tulemused sõltuvad tingimustest.', 'Lisauuring / ravimiinfo; vt lingitud allikat', 'Greipi vältida.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40080, 30036, 2, 'Suhteline biosaadavus; suhtarv 2.84. Isikute vahemik 1,64–4,69', 'n=6; felodipiin 5 mg', 'Biosaadavuse suhe', 'Vahemik pole 95% usaldusvahemik; vasodilatatsiooni kõrvaltoimed sagenesid.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40080, 30037, 2, 'AUC, 1. päev; suhteline muutus 73.0%. —', 'n=12; felodipiin ER 10 mg; ristuv 14-päevane katse', '1 + avaldatud suhteline muutus', 'Erineb Bailey uuringu annusest/ravimvormist.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40080, 30037, 3, 'Cmax, 1. päev; suhteline muutus 138.0%. —', 'Sama katse', '1 + avaldatud suhteline muutus', '+138% tähendab 2,38-kordset, mitte 1,38-kordset taset.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40080, 30037, 4, 'AUC24, 14. päev; suhteline muutus 57.0%. —', 'Sama katse', '1 + avaldatud suhteline muutus', 'Püsiva tarvitamise tingimused.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40080, 30037, 5, 'Cmax, 14. päev; suhteline muutus 114.0%. —', 'Sama katse', '1 + avaldatud suhteline muutus', 'Ei ole annuse kohandamise juhis.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40081, 30036, 1, 'Suurem ekspositsioon; võimalik tugevam hüpotensioon. Biosaadavus 1,34-kordne (1,08–1,69).', 'n=6 tervet meest; nifedipiin 10 mg; ei määra individuaalset riskikordajat.', 'Uuringu kokkuvõte / ravimiinfo', 'Vältida greipi konkreetse preparaadi juhise järgi.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40081, 30036, 2, 'Suhteline biosaadavus; suhtarv 1.34. Isikute vahemik 1,08–1,69', 'n=6; nifedipiin 10 mg', 'Biosaadavuse suhe', 'Ei võrdu kõrvaltoimeriski suurenemisega.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40082, 30038, 1, 'Biosaadavuse ja vererõhku langetava toime suurenemine. Greibikoostoime arvuline suurus viidatud juhises puudub.', 'Toidumõju 4-kordset suurenemist ei tohi pidada greibi mõjuks.', 'Uuringu kokkuvõte / ravimiinfo', 'Greipi ja greibimahla vältida.', 'label', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40083, 30039, 1, 'Väike ekspositsiooni suurenemine; individuaalne varieeruvus. AUC +16%; Cmax +15%; olulist BP/HR lisamuutust ei leitud.', 'n=12; amlodipiin 5 mg + 250 ml mahla. Väike uuring ei välista tundlikke patsiente.', 'Uuringu kokkuvõte / ravimiinfo', 'Greipi mitte kasutada koos ravimiga vastavalt SmPC-le.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40083, 30040, 1, 'Metabolismi mõjutamine.', 'n=12; amlodipiin 5 mg + 250 ml mahla. Väike uuring ei välista tundlikke patsiente.', 'Lisauuring / ravimiinfo; vt lingitud allikat', 'Greipi mitte kasutada koos ravimiga vastavalt SmPC-le.', 'label', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40083, 30039, 2, 'AUC0–72; suhteline muutus 16.0%. BP/HR erinevus mitteoluline', 'n=12; 5 mg + 250 ml mahla', '1 + avaldatud suhteline muutus', 'Väike PK muutus; SmPC siiski ei soovita greipi.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40083, 30039, 3, 'Cmax; suhteline muutus 15.0%. BP/HR erinevus mitteoluline', 'Sama katse', '1 + avaldatud suhteline muutus', 'Mitte kõrvaltoimete 15% suurenemine.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40084, 30041, 1, 'Suurem ekspositsioon; võimalik mõju vererõhule ja südame juhtivusele. S-verapamiili AUC +36%; R-verapamiili AUC +28%.', 'n=9; 120 mg 2 × päevas; mahl 200 ml 2 × päevas. Cmax muutus ei olnud statistiliselt veenev.', 'Uuringu kokkuvõte / ravimiinfo', 'Järgida ravimiinfot ja vältida omal algatusel greibi lisamist.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40084, 30041, 2, 'S-verapamiili AUC0–12; kontroll 215 → koos / teine skeem 292 ng·h/ml; suhteline muutus 36.0%. p=0,04', 'n=9; 120 mg 2× päevas 3 päeva; mahl 200 ml 2× päevas 5 päeva', '1 + avaldatud suhteline muutus', 'BP, HR ja PR-intervall oluliselt ei muutunud.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40084, 30041, 3, 'R-verapamiili AUC0–12; kontroll 800 → koos / teine skeem 1022 ng·h/ml; suhteline muutus 28.0%. p=0,04', 'Sama katse', '1 + avaldatud suhteline muutus', 'Enantiomeeride tulemusi ei liideta.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40085, 30042, 1, 'Tagasihoidlik ekspositsiooni suurenemine. AUC +20 ± 25% (p=0,02); Cmax +22 ± 37% (p=0,14).', 'n=10; mitte-retard 120 mg + 250 ml mahla. Cmax muutus ei olnud statistiliselt oluline.', 'Uuringu kokkuvõte / ravimiinfo', 'Arvestada konkreetse preparaadi juhist.', NULL, 'healthy_volunteers', 10, 'auc_percent_change', 20, NULL, NULL, 0.02, 'diltiaseemi AUC +20 ± 25%; Cmax +22 ± 37% (p=0,14)', 'draft'),
  (40085, 30042, 2, 'AUC0–24; suhteline muutus 20.0%. SD 25%; p=0,02', 'n=10; mitte-retard 120 mg + 250 ml mahla', '1 + avaldatud suhteline muutus', 'Isikute suhteliste muutuste keskmine; suur varieeruvus.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40085, 30042, 3, 'Cmax; suhteline muutus 22.0%. SD 37%; p=0,14', 'Sama katse', '1 + avaldatud suhteline muutus', 'Statistiliselt mitteoluline muutus.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40086, 30043, 1, 'Ebastabiilsem antikoagulatsioon; verejooks. Raske verejooks: OR 2,10 probleemse tarvitamise ja OR 2,36 rohke episoodilise tarvitamise korral.', 'Juhtkontrolluuring, n=570. OR ei ole absoluutrisk ega tingimata põhjuslik mõju; INR-i universaalset muutust ei ole.', 'Uuringu kokkuvõte / ravimiinfo', 'Vältida purjutamist; muutusest teavitada INR-i jälgivat meeskonda. Annust mitte ise muuta.', 'case_control', NULL, 570, 'odds_ratio', 2.1, NULL, NULL, NULL, 'raske verejooks, probleemne tarvitamine; rohke episoodiline tarvitamine OR 2,36', 'draft'),
  (40086, 30044, 1, 'Äge rohke alkohol võib metabolismi pärssida ja INR-i tõsta; krooniline rohke tarvitamine võib metabolismi indutseerida.', 'Juhtkontrolluuring, n=570. OR ei ole absoluutrisk ega tingimata põhjuslik mõju; INR-i universaalset muutust ei ole.', 'Lisauuring / ravimiinfo; vt lingitud allikat', 'Vältida purjutamist; muutusest teavitada INR-i jälgivat meeskonda. Annust mitte ise muuta.', 'label', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40086, 30043, 2, 'Raske verejooks, probleemne tarvitamine; suhtarv 2.1. 95% UV 1,08–4,07', '570 patsienti; 265 juhtu, 305 kontrolli; AUDIT-C järgi probleemne tarvitamine', 'Kohandatud šansisuhe (OR)', 'Vaatlusuuring; OR ei ole absoluutrisk ega kontsentratsioonisuhe.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40086, 30043, 3, 'Raske verejooks, rohke episoodiline tarvitamine; suhtarv 2.36. 95% UV 1,24–4,50', 'Sama uuring; ≥5 alkohoolset jooki korraga', 'Kohandatud šansisuhe (OR)', 'Joogi definitsioon uuringupõhine; ei tõenda põhjuslikkust.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40087, 30045, 1, 'Kõigile antibiootikumidele ühist spetsiifilist alkoholikoostoimet ei ole. Kogu klassi ühine riskikordaja puudub.', 'Järgmised read toovad välja toimeainepõhised erandid.', 'Uuringu kokkuvõte / ravimiinfo', 'Kontrollida konkreetset toimeainet ja ravimvormi.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40088, 30046, 1, 'Hoiatus disulfiraamilaadse reaktsiooni eest: õhetus, iiveldus, südamekloppimine. n=12 uuringus atseetaldehüüdi tõusu ega disulfiraamilaadset reaktsiooni ei leitud.', 'Visapää 2002: 6 ravimit + 6 platseebot; 5 päeva ravi, etanool 0,4 g/kg. Väike uuring ei välista harvaesinevat riski.', 'Uuringu kokkuvõte / ravimiinfo', 'Alkoholist hoiduda ravi ajal ja vähemalt 48 h pärast; kontrollida oma preparaadi infolehte.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40088, 30047, 1, 'Tavapärane ALDH/atseetaldehüüdi seletus ei ole inimestel järjekindlalt kinnitatud.', 'Visapää 2002: 6 ravimit + 6 platseebot; 5 päeva ravi, etanool 0,4 g/kg. Väike uuring ei välista harvaesinevat riski.', 'Lisauuring / ravimiinfo; vt lingitud allikat', 'Alkoholist hoiduda ravi ajal ja vähemalt 48 h pärast; kontrollida oma preparaadi infolehte.', 'label', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40089, 30045, 1, 'Võimaliku disulfiraamilaadse reaktsiooni hoiatus. Arvuline mõju ei ole viidatud juhises esitatud.', 'Praktiline juhis ei ole sama mis tõendatud reaktsioonisagedus.', 'Uuringu kokkuvõte / ravimiinfo', 'Alkoholist hoiduda ravi ajal ja 72 h pärast.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40090, 30048, 1, 'Disulfiraamilaadsed sümptomid, pulsi kiirenemine. Õhetus 5/8 vabatahtlikul; keskmine arteriaalne rõhk ja atseetaldehüüd ei muutunud oluliselt.', 'Kline 1987, topeltpime katse; 2 g × 3 annust, etanool 0,5 g/kg. Väikese katse osakaal ei ole üldine kliiniline sagedus.', 'Uuringu kokkuvõte / ravimiinfo', 'Alkoholist hoiduda ravi ajal ja vähemalt 72 h pärast.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40090, 30049, 1, 'Ravimi struktuuriga seotud alkoholikoostoime; üksnes atseetaldehüüdi kogunemine ei selgita kõiki inimandmeid.', 'Kline 1987, topeltpime katse; 2 g × 3 annust, etanool 0,5 g/kg. Väikese katse osakaal ei ole üldine kliiniline sagedus.', 'Lisauuring / ravimiinfo; vt lingitud allikat', 'Alkoholist hoiduda ravi ajal ja vähemalt 72 h pärast.', 'label', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40090, 30048, 2, 'Õhetusega vabatahtlikud; kontroll — → koos / teine skeem 5 inimest 8-st. —', 'n=8; tsefotetaan 2 g 12 h järel ×3; etanool 0,5 g/kg 1 h pärast 3. annust', 'Osalejate arv', 'Ei ole üldpopulatsiooni esinemissagedus; atseetaldehüüdis olulist erinevust polnud.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40091, 30050, 1, 'Õhetus, higistamine, peavalu, tahhükardia; disulfiraamilaadne reaktsioon. Usaldusväärne riskikordaja siin puudub.', 'Ametlikus ravimiinfos kirjeldatud reaktsioon.', 'Uuringu kokkuvõte / ravimiinfo', 'Vältida alkoholi ravi ajal ja 72 h pärast annust viidatud juhise järgi.', 'label', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40092, 30051, 1, 'Türamiinirikkad kääritatud joogid võivad vererõhku tõsta. SmPC: <100 mg türamiiniga olulist pressorreaktsiooni ei täheldatud.', 'See ei anna universaalset ohutut õlle- või veinikogust; türamiinisisaldus varieerub.', 'Uuringu kokkuvõte / ravimiinfo', 'Vältida suurtes kogustes türamiinirikkaid toite/jooke.', 'label', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40093, 30052, 1, 'Kroonilise rohke alkoholi korral kiirem eliminatsioon, võimalik nõrgem toime. Arvulist muutust ei kinnitatud kättesaadud esmase uuringu abstraktist.', 'Neuvonen 1976: lühem poolväärtusaeg; mõnel patsiendil sisaldus alla terapeutilise läve kord päevas annustamisel. Ei tõenda ühe joogi sama mõju.', 'Uuringu kokkuvõte / ravimiinfo', 'Teavitada ravimi määranud arsti; annust ise mitte muuta.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40094, 30053, 1, 'Maksakahjustuse riskide liitumine. Üldist arvulist riskikordajat ei ole siin kinnitatud.', 'Ravimiinfo põhine juhis.', 'Uuringu kokkuvõte / ravimiinfo', 'Alkoholist hoiduda.', 'label', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40094, 30054, 1, 'Hepatotoksiliste toimete koosesinemine.', 'Ravimiinfo põhine juhis.', 'Lisauuring / ravimiinfo; vt lingitud allikat', 'Alkoholist hoiduda.', 'label', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40095, 30045, 1, 'Puudub kogu klassile laiendatav disulfiraamilaadse reaktsiooni reegel. Spetsiifiline riskikordaja puudub.', 'Ei tähenda, et rohke alkoholi tarvitamine haiguse ajal oleks ohutu.', 'Uuringu kokkuvõte / ravimiinfo', 'Piirata alkoholi ja kontrollida preparaadi juhist.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40095, 30055, 1, 'Peamine praktiline probleem võib olla kõrvaltoimete/halva enesetunde süvenemine.', 'Ei tähenda, et rohke alkoholi tarvitamine haiguse ajal oleks ohutu.', 'Lisauuring / ravimiinfo; vt lingitud allikat', 'Piirata alkoholi ja kontrollida preparaadi juhist.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40096, 30056, 1, 'Hüpoglükeemia, laktatsidoos ja ketoatsidoos on erinevad riskid. Vt toimeainepõhised read.', 'Monoteraapia andmed ei tõenda kooskasutamise ohutust.', 'Uuringu kokkuvõte / ravimiinfo', 'Hinnata kogu raviskeemi; eristada järgnevaid rühmi.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40096, 30057, 1, 'Sõltub ravimist, söömisest, alkoholi kogusest ning neeru- ja maksatalitlusest.', 'Monoteraapia andmed ei tõenda kooskasutamise ohutust.', 'Lisauuring / ravimiinfo; vt lingitud allikat', 'Hinnata kogu raviskeemi; eristada järgnevaid rühmi.', 'label', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40097, 30056, 1, 'Hilinenud hüpoglükeemia, sh järgmisel hommikul. Hommikul vajas ravi 5/6 veini järel vs 0/6 vee järel; madalaim glükoos 1,9–2,9 mmol/l.', 'Turner 2001; 6 I tüüpi diabeediga meest, vein 0,75 g etanooli/kg. Katse ei määra kõigi patsientide sagedust.', 'Uuringu kokkuvõte / ravimiinfo', 'Arvestada hilinenud riskiga ning individuaalse veresuhkru jälgimise/raviplaaniga.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40097, 30056, 2, 'Hommikune hüpoglükeemia, mis vajas ravi; kontroll 0 → koos / teine skeem 5 inimest 6-st. —', 'n=6 I tüüpi diabeediga meest; vein 0,75 g etanooli/kg kell 21; kontroll vesi', 'Osalejate arv', 'Väike ristuv katse; 0-ga jagatud riskikordajat ei arvutata.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40097, 30056, 3, 'Järgmise hommiku söögijärgne glükoosi tipp; kontroll 15 → koos / teine skeem 8.9 mmol/l. p<0,01', 'Sama katse; 5 hüpoglükeemia korral madalaim väärtus 1,9–2,9 mmol/l', 'Keskmised', 'Glükoosikontsentratsioon, mitte insuliini kontsentratsioon; keskmiste SEM 1,5 ja 1,7 mmol/l.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40098, 30058, 1, 'Võimalik raske/pikaajaline hüpoglükeemia; glimepiriidi toime võib ka nõrgeneda. Usaldusväärne ühine riskikordaja puudub.', 'Gliklasiidi juhis kirjeldab hüpoglükeemilise kooma võimalust; glimepiriidi toime võib tugevneda või nõrgeneda.', 'Uuringu kokkuvõte / ravimiinfo', 'Gliklasiidi SmPC: vältida alkoholi ja alkoholi sisaldavaid ravimeid.', 'label', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40098, 30059, 1, 'Insuliini sekretsiooni suurendavale toimele lisandub kompensatsioonireaktsioonide pärssimine.', 'Gliklasiidi juhis kirjeldab hüpoglükeemilise kooma võimalust; glimepiriidi toime võib tugevneda või nõrgeneda.', 'Lisauuring / ravimiinfo; vt lingitud allikat', 'Gliklasiidi SmPC: vältida alkoholi ja alkoholi sisaldavaid ravimeid.', 'label', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40099, 30057, 1, 'Laktatsidoos. Alkoholist tingitud täpset lisariski viidatud juhis ei kvantifitseeri.', 'Laktatsidoos ei ole sama mis hüpoglükeemia.', 'Uuringu kokkuvõte / ravimiinfo', 'Vältida liigset alkoholi.', 'label', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40100, 30060, 1, 'Ketoatsidoos, võimalik ka ilma väga kõrge glükoosita. Alkoholispetsiifiline riskikordaja puudub viidatud ravimiinfos.', 'Empagliflosiini juhises on alkohol üks vallandavatest teguritest.', 'Uuringu kokkuvõte / ravimiinfo', 'Arvestada haiguspäevade ja ketoatsidoosi juhistega; sümptomite korral kiire meditsiiniline hindamine.', 'label', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40101, 30061, 1, 'Monoteraapias väiksem hüpoglükeemiarisk; koos insuliini/sulfonüüluureaga suureneb. Siin viidatud uuringuandmed ei mõõda alkoholi lisamõju.', 'Üldised hüpoglükeemiaandmed, mitte otsene alkoholi koostoimekatse.', 'Uuringu kokkuvõte / ravimiinfo', 'Hinnata kooskasutatavaid ravimeid ja patsiendi seisundit.', 'label', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40101, 30062, 1, 'Glükoosist sõltuv toime; kombinatsioonravi muudab riski.', 'Üldised hüpoglükeemiaandmed, mitte otsene alkoholi koostoimekatse.', 'Lisauuring / ravimiinfo; vt lingitud allikat', 'Hinnata kooskasutatavaid ravimeid ja patsiendi seisundit.', 'label', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40102, 30063, 1, 'Seedetrakti verejooks. Aspiriin >325 mg regulaarne kasutus alkoholi tarvitajatel: RR 7,0; regulaarne ibuprofeen: RR 2,7.', '1224 juhtu, 2945 kontrolli. Need ei ole puhtad alkoholi lisamõju kordajad; otsesed andmed aspiriini/ibuprofeeni, mitte kõigi MSPVA-de kohta.', 'Uuringu kokkuvõte / ravimiinfo', 'Vältida rohket alkoholi; individuaalne hindamine.', NULL, NULL, NULL, 'relative_risk', 7.0, NULL, NULL, NULL, 'aspiriin >325 mg regulaarne kasutus alkoholi tarvitajatel; regulaarne ibuprofeen RR 2,7', 'draft'),
  (40102, 30063, 2, 'Ülemise seedetrakti raske verejooks; suhtarv 7. Statistiliselt oluline', '1224 juhtu/2945 kontrolli; aspiriin regulaarselt vähemalt üle päeva, >325 mg; alkoholi tarvitajate seas', 'Uuringus avaldatud suhteline risk', 'Võrdleb aspiriini kasutust tarvitajatel; ei mõõda ainult alkoholi lisamist aspiriinile.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40102, 30063, 3, 'Ülemise seedetrakti raske verejooks; suhtarv 2.7. Statistiliselt oluline', 'Sama uuring; regulaarne ibuprofeen, annused ühendatud', 'Uuringus avaldatud suhteline risk', 'Juhukasutusel RR 1,2 ja olulist seost ei leitud. Naprokseenile/diklofenakile ei üldistata arvu.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40103, 30064, 1, 'Maksakahjustuse oht eriti üleannuse, alatoitumise ja kroonilise rohke tarvitamise korral. 3-päevases katses ALT tipu keskmine 57 vs 55 IU/l (ravim vs platseebo); olulist erinevust ei olnud.', '443 äsja abstinentset patsienti; 4 g/päev oli uuringuannus, mitte individuaalne soovitus ega jätkuva koosjoomise ohutustõend.', 'Uuringu kokkuvõte / ravimiinfo', 'Mitte ületada oma preparaadi annust; vältida mitme paratsetamooli sisaldava ravimi liitmist.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40103, 30065, 1, 'CYP2E1 induktsioon ja glutatioonipuudus võivad suurendada toksilise metaboliidi mõju.', '443 äsja abstinentset patsienti; 4 g/päev oli uuringuannus, mitte individuaalne soovitus ega jätkuva koosjoomise ohutustõend.', 'Lisauuring / ravimiinfo; vt lingitud allikat', 'Mitte ületada oma preparaadi annust; vältida mitme paratsetamooli sisaldava ravimi liitmist.', 'label', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40103, 30064, 2, 'ALT suurim keskmine aktiivsus; kontroll 55 → koos / teine skeem 57 IU/l. Oluline erinevus puudus', '443 osalejat; 4 g/päev 3 päeva vs platseebo; äsja abstinentsed', 'Keskmised', 'Ei olnud samaaegse pideva alkoholitarvitamise ohutusuuring ega annusesoovitus.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40104, 30066, 1, 'Lisandub sedatsiooni ja hingamisdepressiooni risk. Kindlat universaalset kordajat ei ole.', 'Kombinatsioon säilitab mõlema toimeaine riskid.', 'Uuringu kokkuvõte / ravimiinfo', 'Alkoholist hoiduda; vt opioidide read.', 'label', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40104, 30065, 1, 'Opioidi ja alkoholi kesknärvisüsteemi pärssivate toimete liitumine.', 'Kombinatsioon säilitab mõlema toimeaine riskid.', 'Lisauuring / ravimiinfo; vt lingitud allikat', 'Alkoholist hoiduda; vt opioidide read.', 'label', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
