INSERT INTO translations (text_id, locale_id, text)
VALUES
  (700011, (SELECT id FROM locales WHERE code = 'et'), 'Statiinid ja greip'),
  (700012, (SELECT id FROM locales WHERE code = 'et'), 'CYP3A4 pärssimine võib suurendada nende statiinide plasmakontsentratsiooni. Greibimahla mõju suurus ja kliinilise riski tõlgendus erinevad allikati.'),
  (700013, (SELECT id FROM locales WHERE code = 'et'), 'Kooskasutamise sobivus vajab juhtumipõhist hinnangut. Esitatud vältimissoovituste kõrval on allikas, mis ei pea greibimahla üldist vastunäidustamist põhjendatuks; ühist lõplikku soovitust ei ole kinnitatud.'),
  (700014, (SELECT id FROM locales WHERE code = 'et'), 'Ainult nimetatud statiinid ja juhtumites kirjeldatud tingimused. Mahla kogus ja manustamisaeg on määratud üksnes osas allikates.'),
  (700015, (SELECT id FROM locales WHERE code = 'et'), 'Plasmakontsentratsiooni tõus ei tõenda igal ravimipaaril rabdomüolüüsi. Puudub ühtne patsiendipõhine riskihinnang või annuse muutmise reegel.'),
  (700016, (SELECT id FROM locales WHERE code = 'et'), 'CYP3A4 inhibiitorite grupijäreldust ei laiendata automaatselt kõigile statiinidele ega igale greibikogusele.'),
  (700017, (SELECT id FROM locales WHERE code = 'et'), 'Atorvastatiin, lovastatiin ja simvastatiin.'),
  (700018, (SELECT id FROM locales WHERE code = 'et'), 'Greip, greibimahl ning tugevad CYP3A4 inhibiitorid; need on eraldi määratletud juhtumid.'),
  (700019, (SELECT id FROM locales WHERE code = 'et'), 'Kolmandat kohustuslikku tegurit ei ole kirjeldatud. Greibi ja greibimahla koguseid ei samastata.'),
  (700021, (SELECT id FROM locales WHERE code = 'et'), 'Levotüroksiin ja imendumist mõjutavad tegurid'),
  (700022, (SELECT id FROM locales WHERE code = 'et'), 'Mitme toidu, lisandi ja ravimi kooskasutamisel on kirjeldatud imendumise vähenemist. C-vitamiini puhul on kirjeldatud võimalikku imendumise suurenemist.'),
  (700023, (SELECT id FROM locales WHERE code = 'et'), 'Imendumist vähendavate teguritega täpsustada manustamise ajastust. Esitatud andmed ei anna kõigile teguritele kindlat ajavahemikku ega alust iseseisvaks annuse muutmiseks.'),
  (700024, (SELECT id FROM locales WHERE code = 'et'), 'Teguri ja ravimvormi kaupa. Suukaudse lahuse ja tableti tühja kõhuga biosaadavuse võrdlus ei tõenda lahuse koostoime puudumist kohviga.'),
  (700025, (SELECT id FROM locales WHERE code = 'et'), 'Toidu ja lisandite kohta on ülevaates nimetatud tõendusmaterjali piiratuks. Annused, täpsed manustamisvahed ja patsiendirühmad ei ole kõigi juhtumite kohta esitatud.
