INSERT INTO evidence_findings (interaction_rule_id, evidence_source_id, finding_order, finding_text, limitations_text, source_locator, source_guidance_text, study_design, population, sample_size, effect_metric, effect_value, effect_ci_low, effect_ci_high, p_value, effect_note, status)
VALUES
  (40001, 30001, 1, 'Greip pärsib CYP3A4; esitatud allikakatke soovitab vältida koosmanustamist CYP3A4 inhibiitoritega.', 'Väide puudutab CYP3A4 vahendusel metaboliseeruvaid statiine.', 'Täpset lehekülge/jaotist ei ole alusmaterjalis esitatud.', 'MD soovituse mustand: Vältida greibi tarvitamist selle ravimiga; vajaduse korral arutada raviarstiga.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40002, 30001, 1, 'Greip pärsib CYP3A4; esitatud allikakatke soovitab vältida koosmanustamist CYP3A4 inhibiitoritega.', 'Väide puudutab CYP3A4 vahendusel metaboliseeruvaid statiine.', 'Täpset lehekülge/jaotist ei ole alusmaterjalis esitatud.', 'MD soovituse mustand: Vältida greibi tarvitamist selle ravimiga; vajaduse korral arutada raviarstiga.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40003, 30001, 1, 'Greip pärsib CYP3A4; esitatud allikakatke soovitab vältida koosmanustamist CYP3A4 inhibiitoritega.', 'Väide puudutab CYP3A4 vahendusel metaboliseeruvaid statiine.', 'Täpset lehekülge/jaotist ei ole alusmaterjalis esitatud.', 'MD soovituse mustand: Vältida greibi tarvitamist selle ravimiga; vajaduse korral arutada raviarstiga.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft'),
  (40004, 30002, 1, 'Greibimahl on kliiniliselt oluline CYP3A4 inhibiitor. Teatavate statiinide ja CYP3A4 inhibiitorite kooskasutamisega on seostatud rabdomüolüüsi.', 'Uuringukokkuvõttes ei täpsustata greibimahla kogust ega konkreetse statiini puhul riski suurust.
